import java.util.List;
import java.util.function.Supplier;

public class AttemptLoopTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        int[] tries = {0};
        Supplier<Integer> counter = () -> ++tries[0];
        checkCall("retry returns the first accepted value", 3, () -> AttemptLoop.retry(counter, v -> v >= 3, 5, -1));
        check("retry stopped as soon as it succeeded", 3, tries[0]);

        int[] budget = {0};
        Supplier<Integer> always = () -> ++budget[0];
        checkCall("retry falls back when nothing is accepted", -1, () -> AttemptLoop.retry(always, v -> false, 4, -1));
        check("retry respected maxAttempts", 4, budget[0]);

        int[] untouched = {0};
        checkCall("maxAttempts 0 never calls the action", -1,
                () -> AttemptLoop.retry(() -> ++untouched[0], v -> true, 0, -1));

        int[] flaky = {0};
        Supplier<String> throwsTwice = () -> {
            flaky[0]++;
            if (flaky[0] <= 2) {
                throw new IllegalStateException("not ready");
            }
            return "ok";
        };
        checkCall("a throwing attempt is retried", "ok", () -> AttemptLoop.retry(throwsTwice, v -> true, 5, "none"));

        checkCall("an always-throwing action falls back quietly", "none",
                () -> AttemptLoop.retry(() -> {
                    throw new IllegalStateException("down");
                }, v -> true, 3, "none"));

        List<Supplier<String>> plans = List.of(
                () -> {
                    throw new IllegalStateException("plan A failed");
                },
                () -> "plan B",
                () -> "plan C");
        checkCall("firstAccepted skips the thrower", "plan B",
                () -> AttemptLoop.firstAccepted(plans, v -> true, "none"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

