import java.util.List;
import java.util.function.Predicate;
import java.util.function.Supplier;

public class AttemptLoop {

    public static <T> T retry(Supplier<T> action, Predicate<T> accept, int maxAttempts, T fallback) {
        for (int attempt = 0; attempt < maxAttempts; attempt++) {
            try {
                T result = action.get();
                if (accept.test(result)) {
                    return result;
                }
            } catch (RuntimeException e) {
                // a failed attempt -- try again
            }
        }
        return fallback;
    }

    public static <T> T firstAccepted(List<Supplier<T>> actions, Predicate<T> accept, T fallback) {
        for (Supplier<T> action : actions) {
            try {
                T result = action.get();
                if (accept.test(result)) {
                    return result;
                }
            } catch (RuntimeException e) {
                // move on to the next supplier
            }
        }
        return fallback;
    }
}
